9	/**
10	 * GET /api/invoices/{id}/discount — one invoice's discount breakdown: the subtotal (the sum of its
11	 * line items), the percentage discount taken off it, and the final total (subtotal - discount).
12	 * Derived per request from the invoice's stored {@code discountPct} and its line items, so it always
13	 * reflects the current lines and never stores the total twice. Wired by
14	 * {@code officefloor/rest/api/invoices/{id}/discount.GET.yml}. An unknown invoice id is 404.
15	 */
16	public class InvoiceDiscountGet {
17	
18	    public void service(@HttpPathParameter("id") String id, InvoiceRepository invoices,
19	            LineItemRepository lineItems, ObjectResponse<InvoiceDiscount> response) {
20	        Long invoiceId = Long.valueOf(id);
