22	                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND));
23	        BigDecimal subtotal = BigDecimal.ZERO;
24	        for (LineItem line : lineItems.findByInvoiceIdOrderByIdAsc(invoiceId)) {
25	            if (line.getUnitPrice() != null && line.getQty() != null) {
26	                subtotal = subtotal.add(line.getUnitPrice().multiply(BigDecimal.valueOf(line.getQty())));
