3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Function;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Every domain table, child-before-parent. Referential integrity is dropped around the
34	     * TRUNCATE so the order is only for readability of the FK chain (invoices -> projects ->
35	     * clients). Add a new table here (and a matching {@code seedTable} call) to extend the harness.
36	     */
37	    private static final List<String> TABLES =
38	            List.of("invoice_payments", "invoice_line_items", "invoices", "notes", "tasks",
39	                    "contacts", "project_tags", "projects", "tags", "clients", "app_settings");
40	
41	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
42	    @PostMapping("/reset")
43	    public void reset() {
44	        audit.clear();
45	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
46	        for (String table : TABLES) {
47	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
48	        }
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    public void seed(@RequestBody Map<String, Object> fixture) {
55	        seedTable(fixture, "clients", "INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
56	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email")});
57	        seedTable(fixture, "projects",
58	                "INSERT INTO projects (id, name, client_id, status, archived, budget)"
59	                        + " VALUES (?, ?, ?, ?, ?, ?)",
60	                p -> new Object[] {id(p, "id"), p.get("name"), id(p, "clientId"),
61	                        p.getOrDefault("status", "ACTIVE"), Boolean.TRUE.equals(p.get("archived")),
62	                        p.get("budget") == null ? null : ((Number) p.get("budget")).doubleValue()});
63	        seedTable(fixture, "contacts",
64	                "INSERT INTO contacts (id, name, email, role, client_id, is_primary)"
65	                        + " VALUES (?, ?, ?, ?, ?, ?)",
66	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email"), c.get("role"),
67	                        id(c, "clientId"), Boolean.TRUE.equals(c.get("primary"))});
68	        seedTable(fixture, "tasks", "INSERT INTO tasks (id, title, done, project_id) VALUES (?, ?, ?, ?)",
69	                t -> new Object[] {id(t, "id"), t.get("title"), Boolean.TRUE.equals(t.get("done")),
70	                        id(t, "projectId")});
71	        seedTable(fixture, "notes",
72	                "INSERT INTO notes (id, target_type, target_id, note_text, noted_at) VALUES (?, ?, ?, ?, ?)",
73	                n -> new Object[] {id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
74	                        n.get("at")});
75	        // Notes are pre-seeded AND created through the API in the same spec, so the identity has to
76	        // continue past the seeded ids (a raw insert of an explicit id does not advance H2's
77	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
78	        restartIdentity("notes");
79	        seedTable(fixture, "tags", "INSERT INTO tags (id, name) VALUES (?, ?)",
80	                t -> new Object[] {id(t, "id"), t.get("name")});
81	        seedTable(fixture, "projectTags",
82	                "INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
83	                pt -> new Object[] {id(pt, "projectId"), id(pt, "tagId")});
84	        seedInvoices(fixture);
85	        seedTable(fixture, "payments",
86	                "INSERT INTO invoice_payments (id, invoice_id, amount, paid_on) VALUES (?, ?, ?, ?)",
87	                p -> new Object[] {id(p, "id"), id(p, "invoiceId"),
88	                        ((Number) p.get("amount")).doubleValue(), p.get("date")});
89	        // Payments are pre-seeded AND created through the API in the same spec, so the identity has
90	        // to continue past the seeded ids (a raw insert of an explicit id does not advance H2's
91	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
92	        restartIdentity("invoice_payments");
93	        // The dashboard's reference date for "overdue", a top-level scalar (not a table of rows) so
94	        // the count is deterministic. Absent = the dashboard falls back to today.
95	        Object asOf = fixture.get("asOf");
96	        if (asOf != null) {
97	            jdbc.update("INSERT INTO app_settings (setting_key, setting_value) VALUES ('asOf', ?)",
98	                    asOf.toString());
99	        }
100	    }
101	
102	    /**
103	     * Seed invoices and, nested under each, its line items. An invoice's amount is the sum of its
104	     * lines' qty * unitPrice, so when a fixture lists {@code lineItems} the amount is derived from
105	     * them (the user no longer types one figure); a fixture may still give an explicit
106	     * {@code amount} instead (an invoice with no lines). One method rather than a plain seedTable
107	     * call because the line items live inside each invoice, keyed by the invoice's own id.
108	     */
109	    @SuppressWarnings("unchecked")
110	    private void seedInvoices(Map<String, Object> fixture) {
111	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
112	        if (invoices == null) {
113	            return;
114	        }
115	        for (Map<String, Object> invoice : invoices) {
116	            long invoiceId = id(invoice, "id");
117	            List<Map<String, Object>> lineItems =
118	                    (List<Map<String, Object>>) invoice.get("lineItems");
119	            double amount;
120	            if (invoice.get("amount") != null) {
121	                amount = ((Number) invoice.get("amount")).doubleValue();
122	            } else {
123	                amount = 0.0;
124	                if (lineItems != null) {
125	                    for (Map<String, Object> line : lineItems) {
126	                        amount += ((Number) line.get("qty")).doubleValue()
127	                                * ((Number) line.get("unitPrice")).doubleValue();
128	                    }
129	                }
130	            }
131	            double discountPct = invoice.get("discountPct") == null ? 0.0
132	                    : ((Number) invoice.get("discountPct")).doubleValue();
133	            jdbc.update("INSERT INTO invoices"
134	                    + " (id, project_id, amount, status, issued_date, due_date, discount_pct)"
135	                    + " VALUES (?, ?, ?, ?, ?, ?, ?)",
136	                    invoiceId, id(invoice, "projectId"), amount,
137	                    invoice.getOrDefault("status", "DRAFT"), invoice.get("issuedDate"),
138	                    invoice.get("dueDate"), discountPct);
139	            if (lineItems != null) {
140	                for (Map<String, Object> line : lineItems) {
141	                    jdbc.update("INSERT INTO invoice_line_items"
142	                            + " (id, invoice_id, description, qty, unit, unit_price)"
143	                            + " VALUES (?, ?, ?, ?, ?, ?)",
144	                            id(line, "id"), invoiceId, line.get("description"),
145	                            ((Number) line.get("qty")).intValue(),
146	                            line.getOrDefault("unit", ""),
147	                            ((Number) line.get("unitPrice")).doubleValue());
148	                }
149	            }
150	        }
151	    }
152	
153	    /**
154	     * Insert every row the fixture supplies under {@code key}, mapping each to the {@code sql}
155	     * parameters with {@code toParams}. Absent key = nothing to seed. One call per table keeps
156	     * seeding a new table a single additive line.
157	     */
158	    @SuppressWarnings("unchecked")
159	    private void seedTable(Map<String, Object> fixture, String key, String sql,
160	            Function<Map<String, Object>, Object[]> toParams) {
161	        List<Map<String, Object>> rows = (List<Map<String, Object>>) fixture.get(key);
162	        if (rows == null) {
163	            return;
164	        }
165	        for (Map<String, Object> row : rows) {
166	            // Explicit fixture id (JPA save() would ignore it — the spec asserts by these ids).
167	            jdbc.update(sql, toParams.apply(row));
168	        }
169	    }
170	
171	    /**
172	     * Continue a table's IDENTITY past the highest seeded id, so an API insert after seeding gets a
173	     * fresh id instead of colliding with a fixture row (H2 does not advance the sequence for the
174	     * explicit ids a JdbcTemplate seed inserts).
175	     */
176	    private void restartIdentity(String table) {
177	        Long max = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM " + table, Long.class);
178	        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + (max + 1));
179	    }
180	
181	    /** Read a fixture field as a table id (JSON numbers arrive as {@link Number}). */
182	    private static long id(Map<String, Object> row, String key) {
183	        return ((Number) row.get(key)).longValue();
184	    }
185	}
